/**
 * 시도명과 시군구명으로 해당 지역의 24대 지표 6개년 데이터 조회
 */
export function get_region_indicators_trend(sido_name: string, sigungu_name: string): {
  indicators: { [code: string]: 지표_시계열_데이터 };
  sido_indicators?: { [code: string]: 지표_시계열_데이터 };
  national_indicators: { [code: string]: 지표_시계열_데이터 };
} {
  // 매칭 시도
  let matched_key = Object.keys(시군구_지표_시계열).find(k => k.includes(sigungu_name));
  if (!matched_key) {
    const sgg_clean = sigungu_name.replace(/(시|군|구)$/, '');
    matched_key = Object.keys(시군구_지표_시계열).find(k => k.includes(sgg_clean));
  }

  const default_sigungu = matched_key ? 시군구_지표_시계열[matched_key].indicators : 시군구_지표_시계열[Object.keys(시군구_지표_시계열)[0]].indicators;

  // 시도 매칭
  const sido_key = Object.keys(시도_지표_시계열).find(s => sido_name.includes(s) || s.includes(sido_name));
  const sido_ind = sido_key ? 시도_지표_시계열[sido_key] : undefined;

  return {
    indicators: default_sigungu,
    sido_indicators: sido_ind,
    national_indicators: 전국_지표_시계열,
  };
}
